import datetime

def derive(record):
    derived = {}

    # Determine if the study is an applicable clinical trial based on the definitions
    study_type = record.get('protocolSection', {}).get('designModule', {}).get('studyType')
    primary_purpose = record.get('protocolSection', {}).get('designModule', {}).get('designInfo', {}).get('primaryPurpose')
    is_fda_regulated_device = record.get('protocolSection', {}).get('oversightModule', {}).get('isFdaRegulatedDevice')
    is_fda_regulated_drug = record.get('protocolSection', {}).get('oversightModule', {}).get('isFdaRegulatedDrug')
    locations = record.get('protocolSection', {}).get('contactsLocationsModule', {}).get('locations', [])
    interventions = record.get('protocolSection', {}).get('armsInterventionsModule', {}).get('interventions', [])

    if study_type == 'INTERVENTIONAL':
        if is_fda_regulated_device and primary_purpose != 'DEVICE_FEASIBILITY':
            derived['is_applicable_trial'] = True
        elif is_fda_regulated_drug and 'PHASE1' not in [phase for phase in record.get('protocolSection', {}).get('designModule', {}).get('phases', [])]:
            derived['is_applicable_trial'] = True
        else:
            derived['is_applicable_trial'] = False
    else:
        derived['is_applicable_trial'] = False

    # Check if there is at least one location within the US or territories
    us_location = any(location.get('country') == 'United States' for location in locations)
    derived['us_location'] = us_location

    # Calculate the submission deadline
    primary_completion_date_str = record.get('protocolSection', {}).get('statusModule', {}).get('primaryCompletionDateStruct', {}).get('date')
    if primary_completion_date_str:
        try:
            primary_completion_date = datetime.datetime.strptime(primary_completion_date_str, "%Y-%m-%d")
            derived['submission_deadline'] = (primary_completion_date + datetime.timedelta(days=365)).strftime("%Y-%m-%d")
        except ValueError:
            derived['submission_deadline'] = None

    return derived
